entries[119207] = { ["name"] = "Fleischerbeil", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nKauf erfordert eine Fertigkeit von 100 in der Kochkunst von Draenor.\nVerkaufspreis:" }
entries[119208] = { ["name"] = "Arkanum des Propheten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein Erinnerungskristall, in dem einige der letzten Gedanken des Propheten aufgezeichnet sind. Bringt ihn zum Denkmal des Propheten Velen unter dem Kolosseum des Lichts.\"" }
entries[119209] = { ["name"] = "Verärgerter Braufestbrief", ["text"] = "Benutzen: Kündigt Eure Mitgliedschaft im Bräu-des-Monats-Klub e.V.\n\"WARNUNG: Sobald der wütende Brief verschickt wurde, könnt Ihr nie wieder dem Klub beitreten!\"" }
entries[119210] = { ["name"] = "Hearthstone-Spielbrett", ["text"] = "Spielzeug\nBenutzen: Stellt ein Hearthstone-Spielbrett auf und zeigt allen, die Ihr kennt, dass Ihr bereit für eine Partie seid! (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[119211] = { ["name"] = "Goldene Hearthstone-Karte: Lord Jaraxxus", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Vernichtet Euren Helden und ersetzt ihn durch Lord Jaraxxus. (2 Std., 30 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\"In tadellosem Zustand.\"\nVerkaufspreis:" }
entries[119212] = { ["name"] = "Siegerhand", ["text"] = "Spielzeug\nBenutzen: Zeigt allen, dass Ihr gerade eine Hearthstone-Partie gewonnen habt! (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[119213] = { ["name"] = "Unnötiger Stachel", ["text"] = "Einzigartig (20)\nBenutzen: Platziert einen Stachel.\n\"Eine Frage des Stils.\"\nVerkaufspreis:" }
entries[119215] = { ["name"] = "Robognomobulator", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verwandelt Euch in einen Aufziehgnom. (1 Stunde Abklingzeit)\n\"Jepetto Spaßbrumm hat jahrelang daran gearbeitet, einen Weg zu finden, alles in ein Spielzeug zu verwandeln.\"" }
entries[119216] = { ["name"] = "Superklebrige Glitzerbombe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt Euer Ziel wie einen Diamanten in der Sonne glitzern, wodurch es 15 Sek. lang weder Verstohlenheit noch Unsichtbarkeit einsetzen kann. Kann nur in Draenor genutzt werden. (2 Min Abklingzeit)" }
