entries[119224] = { ["name"] = "Feindesjäger", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n8 - 16 Schaden Geschwindigkeit 3.60\n(3.3 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 5 Vielseitigkeit\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
