entries[119226] = { ["name"] = "Rumskugels Rumser", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n7 - 13 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 100 / 100\nAnlegen: Eure Angriffe haben eine Chance, bei Aufprall zu explodieren und 29 Feuerschaden zu verursachen. (Procchance: 15%, 1.417Min. Abklingzeit)\nVerkaufspreis:" }
entries[119227] = { ["name"] = "Morgos unaufhaltsamer Rammhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
