entries[120027] = { ["name"] = "Lederschiftung des wilden Aspiranten", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nSchulter Leder\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 85 / 85\nKlassen: Schurke\nBenötigt eine Horde-Rasse\nGewänder des Gladiators (0/5)\nLedertunika des Gladiators\nLederhelm des Gladiators\nLederhandschuhe des Gladiators\nLederschiftung des Gladiators\nLederbeinschützer des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Meucheln: Einen Zauber mit einem Tritt erfolgreich zu unterbrechen erzeugt 3 Combopunkte. (2) Set Gesetzlosigkeit: Einen Zauber mit einem Tritt erfolgreich zu unterbrechen erzeugt 3 Combopunkte. (2) Set Täuschung: Einen Zauber mit einem Tritt erfolgreich zu unterbrechen erzeugt 3 Combopunkte.\n(4) Set Meucheln: Wenn Ihr 'Verschwinden' einsetzt, erhaltet Ihr 5 Combopunkte, und die kritische Trefferchance Eures nächsten Einsatzes von 'Verstümmeln' oder 'Vergiften' wird um 10% erhöht.\n(4) Set Gesetzlosigkeit: Wenn Ihr 'Verschwinden' einsetzt, erhaltet Ihr 5 Combopunkte, und die kritische Trefferchance Eures nächsten Einsatzes von 'Säbelhieb', 'Durchstoßen', 'Zwischen die Augen' oder 'Hinterhalt' wird um 100% erhöht.\n(4) Set Täuschung: 'Finte' erhöht außerdem 5 Sek. lang Eure Vielseitigkeit um 140 .\nVerkaufspreis:" }
entries[120028] = { ["name"] = "Ringpanzerrüstung des wilden Aspiranten", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nBrust Kette\n11 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 140 / 140\nKlassen: Schamane\nBenötigt eine Horde-Rasse\nKriegsrausch des Gladiators (0/5)\nRingpanzerrüstung des Gladiators\nRingpanzerhelm des Gladiators\nRingpanzerstulpen des Gladiators\nRingpanzerschiftung des Gladiators\nRingpanzergamaschen des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Elementar: Verringert die Abklingzeit von 'Verhexung' um 15 Sek.\n(2) Set Verstärkung: Wenn Ihr 'Wildgeist' aktiviert, wird die Dauer aller auf Euch gewirkten Kontrollverlusteffekte 30 Sek. lang um 25% verringert.\n(2) Set Wiederherstellung: Wenn Ihr einen schädlichen Magieeffekt oder einen Fluch von einem Verbündeten bannt, erhält dieser 10 Sek. lang 150 Vielseitigkeit.\n(4) Set Elementar: Nach dem Beschwören eines Elementars seid Ihr für 15 Sek. gegen Stille- und Unterbrechungseffekte immun.\n(4) Set Verstärkung: 'Windzorn' verursacht jetzt 2 weitere Male Schaden.\n(4) Set Wiederherstellung: Wenn das Ziel Eures Effekts 'Springflut' unter 50% Gesundheit fällt, wird die Dauer aufgefrischt.\nVerkaufspreis:" }
entries[120029] = { ["name"] = "Ringpanzerstulpen des wilden Aspiranten", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nHände Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 50 / 50\nKlassen: Schamane\nBenötigt eine Horde-Rasse\nKriegsrausch des Gladiators (0/5)\nRingpanzerrüstung des Gladiators\nRingpanzerhelm des Gladiators\nRingpanzerstulpen des Gladiators\nRingpanzerschiftung des Gladiators\nRingpanzergamaschen des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Elementar: Verringert die Abklingzeit von 'Verhexung' um 15 Sek.\n(2) Set Verstärkung: Wenn Ihr 'Wildgeist' aktiviert, wird die Dauer aller auf Euch gewirkten Kontrollverlusteffekte 30 Sek. lang um 25% verringert.\n(2) Set Wiederherstellung: Wenn Ihr einen schädlichen Magieeffekt oder einen Fluch von einem Verbündeten bannt, erhält dieser 10 Sek. lang 150 Vielseitigkeit.\n(4) Set Elementar: Nach dem Beschwören eines Elementars seid Ihr für 15 Sek. gegen Stille- und Unterbrechungseffekte immun.\n(4) Set Verstärkung: 'Windzorn' verursacht jetzt 2 weitere Male Schaden.\n(4) Set Wiederherstellung: Wenn das Ziel Eures Effekts 'Springflut' unter 50% Gesundheit fällt, wird die Dauer aufgefrischt.\nVerkaufspreis:" }
